From d4a359d29df77694a310064aec0feb30ffe5b24a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:15:07 +0100
Subject: [PATCH] containments/desktop: let the rename field take typing in
 panels

Panels don't take keyboard focus by default, so text typed into the
rename field of a Folder View shown inline in a panel went to the
desktop instead. Request input focus when the field opens or is clicked.

BUG: 524740
---
 .../package/contents/ui/RenameEditor.qml      | 23 +++++++++++++++++++
 1 file changed, 23 insertions(+)

diff --git a/containments/desktop/package/contents/ui/RenameEditor.qml b/containments/desktop/package/contents/ui/RenameEditor.qml
index bc65b7f1b1..7d9d7e71ce 100644
--- a/containments/desktop/package/contents/ui/RenameEditor.qml
+++ b/containments/desktop/package/contents/ui/RenameEditor.qml
@@ -10,6 +10,7 @@ import QtQuick.Controls as QQC2


 import org.kde.plasma.plasmoid
+import org.kde.plasma.core as PlasmaCore
 import org.kde.plasma.components as PlasmaComponents
 import org.kde.kirigami as Kirigami

@@ -71,6 +72,7 @@ PlasmaComponents.ScrollView {

         onTargetItemChanged: {
             if (targetItem !== null) {
+                requestKeyboardFocus();
                 var xy = getXY();
                 root.x = xy[0];
                 root.y = xy[1];
@@ -128,6 +130,27 @@ PlasmaComponents.ScrollView {

         onTextChanged: adjustSize();

+        onPressed: {
+            if (requestKeyboardFocus()) {
+                forceActiveFocus();
+            }
+        }
+
+        onActiveFocusChanged: {
+            if (!activeFocus && Plasmoid.status === PlasmaCore.Types.AcceptingInputStatus) {
+                Plasmoid.status = PlasmaCore.Types.ActiveStatus;
+            }
+        }
+
+        // Panels only take keyboard focus when asked to, and then focus their first item
+        function requestKeyboardFocus() {
+            if (!Window.window || !(Window.window.flags & Qt.WindowDoesNotAcceptFocus)) {
+                return false;
+            }
+            Plasmoid.status = PlasmaCore.Types.AcceptingInputStatus;
+            return true;
+        }
+
         function getXY() {
             if (!targetItem) {
                 return [0,0];
-- 
